SELECT user, IF(MIN(create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType FROM t_link_access_logs WHERE full_short_url = #{fullShortUrl} AND gid = #{gid} AND user IN
#{user}
GROUP BY user

SELECT user, IF(MIN(create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType FROM t_link_access_logs WHERE gid = #{gid} AND user IN
#{user}
GROUP BY user

SELECT full_short_url,
       gid,
       count(USER)          AS pv,
       count(DISTINCT USER) AS uv,
       count(DISTINCT ip)   AS uip
FROM t_link_access_logs
WHERE gid = #{bean.gid}
  AND full_short_url = #{bean.fullShortUrl}
  AND create_time BETWEEN #{bean.startDate} and #{bean.endDate}
GROUP BY full_short_url, gid;
